// work shrinks by half each pass -> O(log n)
for (int i = n; i > 1; i /= 2) {}

void byValue(int x)   { x = 99; }     // photocopy changed
void byRef(int &x)    { x = 99; }     // alias -> original hit
void byPtr(int *x)    { *x = 99; }    // follow address -> original hit

