class Buffer {
    int *data; int size;
public:
    Buffer(int s) : size(s) { data = new int[s]{}; }
    ~Buffer() { delete[] data; }                 // cleanup

    Buffer(const Buffer &other)                  // DEEP copy
        : size(other.size) {
        data = new int[size];                    // OWN memory
        for (int i = 0; i < size; i++)
            data[i] = other.data[i];
    }
};

