long long binPow(long long base, long long exp) {
    long long result = 1;
    while (exp > 0) {
        if (exp & 1) result *= base;  // odd bit -> multiply in
        base *= base;                 // square the base
        exp >>= 1;                    // consume the bit
    }
    return result;
}

